import org.openapitools.jackson.nullable.JsonNullable;
import com.fasterxml.jackson.databind.annotation.JsonSerialize;
import jakarta.persistence.*;

@Entity
@Table(name = "users")
@DynamicUpdate
public class UserEntity {
    @Id
    private Long id;
    private String username;
    private String email;

    // Getters, setters, and JPA lifecycle hooks
}

public class UserPatchDTO {
    private JsonNullable<String> username = JsonNullable.undefined();
    private JsonNullable<String> email = JsonNullable.undefined();

    public JsonNullable<String> getUsername() { return username; }
    public void setUsername(JsonNullable<String> username) { this.username = username; }

    public JsonNullable<String> getEmail() { return email; }
    public void setEmail(JsonNullable<String> email) { this.email = email; }
}

public void applyPatch(UserEntity entity, UserPatchDTO patch) {
    if (patch.getUsername() != null && patch.getUsername().isPresent()) {
        entity.setUsername(patch.getUsername().get());
    }
    if (patch.getEmail() != null && patch.getEmail().isNull()) {
        entity.setEmail(null); // Explicitly clear the field
    } else if (patch.getEmail() != null && patch.getEmail().isPresent()) {
        entity.setEmail(patch.getEmail().get());
    }
}
